import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import computeVisibleCount from './computeVisibleCount';
import { useOverflowItemsShareStore, useShareMemberId, useShareSignature } from './OverflowItemsShare';

const DEFAULT_GAP = 8;
const DEFAULT_SAFETY_GAP = 2;
const DEFAULT_SETTLE = 100;
const DEFAULT_MAX_SETTLE = 400;
const DEFAULT_EXPAND_HYSTERESIS = 16;
const DEFAULT_DEBOUNCE = 100;
const DEFAULT_ITEM_SELECTOR = '[data-overflow-item]';

/**
 * 测量容器剩余空间，决定可露出的 item 数量。
 * Resize 触发的重算走 debounce；itemCount / 配置变化立即重算。
 * 处于 OverflowItems.Share 内时，同签名仅 Leader 测宽，Follower 消费共享结果。
 */
const useOverflowItems = ({
  itemCount = 0,
  items,
  shareKey,
  enabled = true,
  strategy = 'asc',
  gap = DEFAULT_GAP,
  safetyGap = DEFAULT_SAFETY_GAP,
  expandHysteresis = DEFAULT_EXPAND_HYSTERESIS,
  settle = DEFAULT_SETTLE,
  maxSettle = DEFAULT_MAX_SETTLE,
  debounce = DEFAULT_DEBOUNCE,
  beforeReady = 'all',
  itemSelector = DEFAULT_ITEM_SELECTOR,
  observeParent = true
} = {}) => {
  const safeCount = Math.max(0, Number(itemCount) || 0);
  const initialVisible = (() => {
    if (!enabled || safeCount === 0) {
      return safeCount;
    }
    return beforeReady === 'min' ? Math.min(1, safeCount) : safeCount;
  })();

  const shareStore = useOverflowItemsShareStore();
  const memberId = useShareMemberId();
  const signature = useShareSignature({
    shareKey,
    items,
    itemCount: safeCount,
    gap,
    strategy,
    safetyGap,
    expandHysteresis,
    enabled
  });

  const containerRef = useRef(null);
  const measureRef = useRef(null);
  const moreMeasureRef = useRef(null);
  const rafRef = useRef(null);
  const settleTimerRef = useRef(null);
  const debounceTimerRef = useRef(null);
  const lastWidthRef = useRef(0);
  const lastCommittedWidthRef = useRef(0);
  const lastSettleWidthRef = useRef(0);
  const stableSinceRef = useRef(0);
  const itemCountRef = useRef(safeCount);
  const readyRef = useRef(!enabled || safeCount === 0);
  const visibleCountRef = useRef(initialVisible);
  const settleStartedAtRef = useRef(0);
  const roleRef = useRef(null);
  const signatureRef = useRef(signature);
  const shareStoreRef = useRef(shareStore);
  const optionsRef = useRef({
    enabled,
    strategy,
    gap,
    safetyGap,
    expandHysteresis,
    settle,
    maxSettle,
    debounce,
    beforeReady,
    itemSelector,
    observeParent,
    safeCount
  });
  optionsRef.current = {
    enabled,
    strategy,
    gap,
    safetyGap,
    expandHysteresis,
    settle,
    maxSettle,
    debounce,
    beforeReady,
    itemSelector,
    observeParent,
    safeCount
  };
  signatureRef.current = signature;
  shareStoreRef.current = shareStore;

  const [containerEl, setContainerEl] = useState(null);
  const [visibleCount, setVisibleCount] = useState(() => initialVisible);
  const [ready, setReady] = useState(() => !enabled || safeCount === 0);
  const [role, setRole] = useState(null);

  const isFollower = role === 'follower';
  // Share 内：仅 Leader 测宽；角色未定时先不挂测量层，避免 Follower 首帧渲染测量 DOM
  const shouldMeasure = !signature ? true : role === 'leader';

  const setContainerRef = useCallback(node => {
    containerRef.current = node;
    setContainerEl(node || null);
  }, []);

  const setMeasureRef = useCallback(node => {
    measureRef.current = node;
  }, []);

  const setMoreMeasureRef = useCallback(node => {
    moreMeasureRef.current = node;
  }, []);

  const clearSettleTimer = useCallback(() => {
    if (settleTimerRef.current) {
      window.clearTimeout(settleTimerRef.current);
      settleTimerRef.current = null;
    }
  }, []);

  const clearDebounceTimer = useCallback(() => {
    if (debounceTimerRef.current) {
      window.clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }
  }, []);

  const clearRaf = useCallback(() => {
    if (rafRef.current) {
      window.cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
  }, []);

  const applySharedState = useCallback(state => {
    if (!state) {
      return;
    }
    visibleCountRef.current = state.visibleCount;
    readyRef.current = state.ready;
    setVisibleCount(prev => (prev === state.visibleCount ? prev : state.visibleCount));
    setReady(prev => (prev === state.ready ? prev : state.ready));
  }, []);

  const publishSharedState = useCallback((nextCount, isReady) => {
    const store = shareStoreRef.current;
    const sig = signatureRef.current;
    if (!store || !sig || roleRef.current === 'follower') {
      return;
    }
    store.publish(sig, { visibleCount: nextCount, ready: isReady });
  }, []);

  const getWidths = useCallback(() => {
    const { safeCount: count, itemSelector: selector } = optionsRef.current;
    const container = containerRef.current;
    const measureEl = measureRef.current;
    if (!container || !measureEl) {
      return null;
    }

    const containerWidth = container.clientWidth;
    if (containerWidth <= 0) {
      return null;
    }

    const itemNodes = measureEl.querySelectorAll(selector);
    if (!itemNodes.length) {
      return null;
    }

    const moreWidth = moreMeasureRef.current?.getBoundingClientRect().width || 0;
    if (count > 1 && moreWidth <= 0) {
      return null;
    }

    const itemWidths = Array.from(itemNodes, node => node.getBoundingClientRect().width);
    if (itemWidths.some(width => width <= 0)) {
      return null;
    }

    return { containerWidth, itemWidths, moreWidth };
  }, []);

  const commitCount = useCallback(
    (nextCount, containerWidth) => {
      clearSettleTimer();
      settleStartedAtRef.current = 0;
      stableSinceRef.current = 0;
      visibleCountRef.current = nextCount;
      readyRef.current = true;
      lastCommittedWidthRef.current = containerWidth;
      lastWidthRef.current = containerWidth;
      lastSettleWidthRef.current = containerWidth;
      setVisibleCount(prev => (prev === nextCount ? prev : nextCount));
      setReady(true);
      publishSharedState(nextCount, true);
    },
    [clearSettleTimer, publishSharedState]
  );

  const calculateByWidth = useCallback(() => {
    if (roleRef.current === 'follower') {
      return;
    }

    const { enabled: isEnabled, strategy: strat, gap: gapPx, safetyGap: safety, expandHysteresis: hysteresis, settle, maxSettle, beforeReady: before, safeCount: count } = optionsRef.current;

    if (!isEnabled || !count) {
      visibleCountRef.current = count;
      readyRef.current = true;
      setVisibleCount(prev => (prev === count ? prev : count));
      setReady(true);
      clearSettleTimer();
      publishSharedState(count, true);
      return;
    }

    const widths = getWidths();
    if (!widths) {
      if (!readyRef.current) {
        if (!settleStartedAtRef.current) {
          settleStartedAtRef.current = Date.now();
        }
        if (Date.now() - settleStartedAtRef.current >= maxSettle) {
          const fallback = before === 'min' ? Math.min(1, count) : count;
          commitCount(fallback, containerRef.current?.clientWidth || lastSettleWidthRef.current || 0);
          return;
        }
        clearSettleTimer();
        settleTimerRef.current = window.setTimeout(() => {
          settleTimerRef.current = null;
          calculateByWidth();
        }, settle);
      }
      return;
    }

    const nextCount = computeVisibleCount({
      containerWidth: widths.containerWidth,
      itemWidths: widths.itemWidths,
      moreWidth: widths.moreWidth,
      gap: gapPx,
      strategy: strat,
      safetyGap: safety
    });
    const { containerWidth } = widths;

    if (!readyRef.current) {
      if (!settleStartedAtRef.current) {
        settleStartedAtRef.current = Date.now();
      }

      if (Math.abs(containerWidth - lastSettleWidthRef.current) >= 1) {
        lastSettleWidthRef.current = containerWidth;
        stableSinceRef.current = Date.now();
        clearSettleTimer();
        settleTimerRef.current = window.setTimeout(() => {
          settleTimerRef.current = null;
          calculateByWidth();
        }, settle);
        return;
      }

      if (!stableSinceRef.current) {
        stableSinceRef.current = Date.now();
      }

      const stableFor = Date.now() - stableSinceRef.current;
      const waited = Date.now() - settleStartedAtRef.current;

      if (stableFor >= settle || waited >= maxSettle) {
        commitCount(nextCount, containerWidth);
        return;
      }

      clearSettleTimer();
      settleTimerRef.current = window.setTimeout(
        () => {
          settleTimerRef.current = null;
          calculateByWidth();
        },
        Math.max(settle - stableFor, 16)
      );
      return;
    }

    if (nextCount === visibleCountRef.current) {
      lastWidthRef.current = containerWidth;
      return;
    }

    if (nextCount > visibleCountRef.current && containerWidth - lastCommittedWidthRef.current < hysteresis) {
      return;
    }

    commitCount(nextCount, containerWidth);
  }, [clearSettleTimer, commitCount, getWidths, publishSharedState]);

  const scheduleCalculateImmediate = useCallback(() => {
    if (roleRef.current === 'follower') {
      return;
    }
    clearDebounceTimer();
    clearRaf();
    rafRef.current = window.requestAnimationFrame(() => {
      rafRef.current = window.requestAnimationFrame(() => {
        rafRef.current = null;
        calculateByWidth();
      });
    });
  }, [calculateByWidth, clearDebounceTimer, clearRaf]);

  const scheduleCalculateDebounced = useCallback(() => {
    if (roleRef.current === 'follower') {
      return;
    }
    const wait = optionsRef.current.debounce;
    if (!(wait > 0)) {
      scheduleCalculateImmediate();
      return;
    }
    clearDebounceTimer();
    debounceTimerRef.current = window.setTimeout(() => {
      debounceTimerRef.current = null;
      scheduleCalculateImmediate();
    }, wait);
  }, [clearDebounceTimer, scheduleCalculateImmediate]);

  useLayoutEffect(() => {
    if (!shareStore || !signature) {
      roleRef.current = null;
      setRole(null);
      return undefined;
    }

    const handle = shareStore.register(signature, memberId, {
      onRoleChange: nextRole => {
        const prevRole = roleRef.current;
        roleRef.current = nextRole;
        setRole(nextRole);
        if (prevRole === 'follower' && nextRole === 'leader') {
          const cached = shareStore.getState(signature);
          if (cached) {
            applySharedState(cached);
          }
          settleStartedAtRef.current = 0;
          stableSinceRef.current = 0;
          // 升为 Leader 后由下方 measure effect 触发重测
        }
      },
      onStateChange: state => {
        if (roleRef.current === 'follower') {
          applySharedState(state);
        }
      }
    });

    roleRef.current = handle.role;
    setRole(handle.role);
    if (handle.state) {
      applySharedState(handle.state);
    }

    return () => {
      handle.unregister();
      roleRef.current = null;
    };
  }, [shareStore, signature, memberId, applySharedState]);

  useLayoutEffect(() => {
    if (isFollower) {
      clearRaf();
      clearSettleTimer();
      clearDebounceTimer();
      return undefined;
    }

    if (itemCountRef.current !== safeCount) {
      itemCountRef.current = safeCount;
      const nextReady = !enabled || safeCount === 0;
      const nextVisible = nextReady ? safeCount : beforeReady === 'min' ? Math.min(1, safeCount) : safeCount;
      visibleCountRef.current = nextVisible;
      readyRef.current = nextReady;
      settleStartedAtRef.current = 0;
      stableSinceRef.current = 0;
      lastSettleWidthRef.current = 0;
      clearSettleTimer();
      clearDebounceTimer();
      setVisibleCount(nextVisible);
      setReady(nextReady);
      if (nextReady) {
        publishSharedState(nextVisible, true);
      }
    }

    scheduleCalculateImmediate();
    return () => {
      clearRaf();
      clearSettleTimer();
      clearDebounceTimer();
    };
  }, [safeCount, enabled, strategy, gap, safetyGap, beforeReady, settle, maxSettle, expandHysteresis, isFollower, role, scheduleCalculateImmediate, clearSettleTimer, clearDebounceTimer, clearRaf, publishSharedState]);

  useEffect(() => {
    if (isFollower || !enabled || !containerEl) {
      return undefined;
    }

    const onWidthChange = nextWidth => {
      if (Math.abs(nextWidth - lastWidthRef.current) < 1) {
        return;
      }
      lastWidthRef.current = nextWidth;
      scheduleCalculateDebounced();
    };

    const observer = new ResizeObserver(entries => {
      const entry = entries.find(item => item.target === containerEl) || entries[0];
      const nextWidth = entry?.contentRect?.width ?? containerEl.clientWidth;
      onWidthChange(nextWidth);
    });

    lastWidthRef.current = containerEl.clientWidth;
    observer.observe(containerEl);
    if (observeParent && containerEl.parentElement) {
      observer.observe(containerEl.parentElement);
    }

    return () => {
      observer.disconnect();
      clearRaf();
      clearSettleTimer();
      clearDebounceTimer();
    };
  }, [containerEl, enabled, observeParent, isFollower, scheduleCalculateDebounced, clearRaf, clearSettleTimer, clearDebounceTimer]);

  const hiddenCount = Math.max(0, safeCount - visibleCount);

  return {
    setContainerRef,
    setMeasureRef,
    setMoreMeasureRef,
    visibleCount,
    ready,
    hiddenCount,
    role,
    shouldMeasure
  };
};

export default useOverflowItems;
